<?= $this->extend('layouts/auth') ?><?= $this->section('content') ?><main class="flex min-h-screen items-center justify-center p-4"><section class="card w-full max-w-md p-6 sm:p-8"><h1 class="text-2xl font-semibold">Choose a new password</h1><?php if(session('error')): ?><p class="mt-3 rounded-lg bg-red-50 p-3 text-sm text-red-800"><?= esc(session('error')) ?></p><?php endif ?><?php if(!empty($invalidEmailToken)): ?><p class="mt-3 rounded-lg bg-red-50 p-3 text-sm text-red-800">This email reset link is invalid or expired.</p><a class="mt-4 inline-block text-accent underline" href="<?= site_url('forgot-password') ?>">Request a new link</a><?php else: ?><form class="mt-6 space-y-4" method="post" action="<?= site_url('reset-password') ?>"><?= csrf_field() ?><?php if(!empty($emailToken)): ?><input type="hidden" name="email_token" value="<?= esc($emailToken) ?>"><?php else: ?><div><label class="form-label" for="token">6-digit SMS code</label><input class="form-control" id="token" name="token" inputmode="numeric" minlength="6" maxlength="6" pattern="[0-9]{6}" required></div><?php endif ?><?= view('components/form/input',['id'=>'password','name'=>'password','type'=>'password','label'=>'New password','required'=>true]) ?><?= view('components/form/input',['id'=>'password_confirm','name'=>'password_confirm','type'=>'password','label'=>'Confirm password','required'=>true]) ?><button class="btn-primary w-full" type="submit">Reset password</button></form><?php endif ?></section></main><?= $this->endSection() ?>
